#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    long long time;
    long long change;
    cin >> n >> m >> time >> change;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    const int INF = 1000000000;
    vector<int> d1(n + 1, INF), d2(n + 1, INF);
    d1[1] = 0;
    vector<pair<int, int>> queue;
    queue.push_back({1, 0});
    for (size_t i = 0; i < queue.size(); i++) {
        int v = queue[i].first, d = queue[i].second;
        for (int w : adj[v]) {
            int nd = d + 1;
            if (nd < d1[w]) {
                d1[w] = nd;
                queue.push_back({w, nd});
            } else if (d1[w] < nd && nd < d2[w]) {
                d2[w] = nd;
                queue.push_back({w, nd});
            }
        }
    }
    long long clock = 0;
    for (int step = 0; step < d2[n]; step++) {
        if ((clock / change) % 2 == 1) clock = (clock / change + 1) * change;
        clock += time;
    }
    cout << clock << "\n";

    return 0;
}

