import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long time = Long.parseLong(next());
        long change = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        int[] head = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            head[(int) edges[i][0] + 1]++;
            head[(int) edges[i][1] + 1]++;
        }
        for (int v = 1; v <= nodes; v++) head[v + 1] += head[v];
        int[] to = new int[2 * edges.length];
        int[] fill = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            int a = (int) edges[i][0], b = (int) edges[i][1];
            to[head[a] + fill[a]] = b;
            fill[a]++;
            to[head[b] + fill[b]] = a;
            fill[b]++;
        }
        final int INF = 1000000000;
        int[] d1 = new int[nodes + 1];
        int[] d2 = new int[nodes + 1];
        Arrays.fill(d1, INF);
        Arrays.fill(d2, INF);
        d1[1] = 0;
        int[] queueNode = new int[2 * nodes + 2];
        int[] queueDist = new int[2 * nodes + 2];
        int qh = 0, qt = 0;
        queueNode[qt] = 1;
        queueDist[qt] = 0;
        qt++;
        while (qh < qt) {
            int v = queueNode[qh], d = queueDist[qh];
            qh++;
            for (int k = head[v]; k < head[v + 1]; k++) {
                int w = to[k];
                int nd = d + 1;
                if (nd < d1[w]) {
                    d1[w] = nd;
                    queueNode[qt] = w;
                    queueDist[qt] = nd;
                    qt++;
                } else if (d1[w] < nd && nd < d2[w]) {
                    d2[w] = nd;
                    queueNode[qt] = w;
                    queueDist[qt] = nd;
                    qt++;
                }
            }
        }
        long clock = 0;
        for (int step = 0; step < d2[nodes]; step++) {
            if ((clock / change) % 2 == 1) clock = (clock / change + 1) * change;
            clock += time;
        }
        System.out.println(clock);
    }
}
